verification_receipts.patch_excerpt:
diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..cd4128a 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -185,4 +185,48 @@ for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command',
 }
 assert.equal(replay.model_status, 'unknown');

+// Adversarial model substitution: a trusted observation naming a different model
+// can never pass, the substituted name is surfaced instead of hidden, and the
+// telemetry the runtime never reported stays unknown rather than being inferred.
+const substituted = Object.freeze({ model: 'claude-sonnet-4-5', trusted: true, source: 'codex-jsonl' });
+assert.deepEqual(profiles.evaluateModelProof(local, substituted), {
+  requested_model: local.model, observed_model: 'claude-sonnet-4-5',
+  status: 'failed', reason_code: 'MODEL_OBSERVATION_MISMATCH',
+});
+// Near misses are substitutions too: the match is exact, not folded or prefixed.
+for (const near of ['QWEN3-CODER:30B', 'qwen3-coder', 'qwen3-coder:30b-instruct']) {
+  const nearProof = profiles.evaluateModelProof(local, { model: near, trusted: true });
+  assert.equal(nearProof.status, 'failed', near);
+  assert.equal(nearProof.reason_code, 'MODEL_OBSERVATION_MISMATCH', near);
+}
+
+// A genuine, cryptographically verified receipt cannot launder the substitution.
+const verification = profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput });
+const missionSubstituted = profiles.missionControlExecutorState({
+  profile: local, observation: substituted, wrapper, verification,
+});
+assert.equal(missionSubstituted.receipt_status, 'verified');
+assert.equal(missionSubstituted.model_status, 'failed');
+assert.equal(missionSubstituted.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.equal(missionSubstituted.requested_model, local.model);
+assert.equal(missionSubstituted.observed_model, 'claude-sonnet-4-5');
+assert.equal(missionSubstituted.cost, null);
+assert.equal(missionSubstituted.cost_status, 'unknown');
+assert.equal(missionSubstituted.duration_ms, null);
+assert.equal(missionSubstituted.duration_status, 'unknown');
+assert.equal(missionSubstituted.tokens, null);
+assert.equal(missionSubstituted.tokens_status, 'unknown');
+
+const substitutedReplay = profiles.publicExecutorReplay({
+  profile: local, observation: substituted, wrapper,
+});
+assert.equal(substitutedReplay.model_status, 'failed');
+assert.equal(substitutedReplay.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.equal(substitutedReplay.requested_model, local.model);
+assert.equal(substitutedReplay.observed_model, 'claude-sonnet-4-5');
+assert.deepEqual(
+  [substitutedReplay.cost_status, substitutedReplay.duration_status, substitutedReplay.tokens_status],
+  ['unknown', 'unknown', 'unknown'],
+);
+
 process.stdout.write('Executor profiles passed: strict profiles, canonical digests, literal invocations, bound receipts, and honest model proof.\n');
